import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Lightweight i18n provider with English + Swahili.
/// All user-facing strings live here.
class FFLocale extends ChangeNotifier {
  static const prefsKey = 'ff.locale';

  Locale _locale = const Locale('en');
  Locale get locale => _locale;

  void set(Locale l) {
    if (_supported.contains(l.languageCode)) {
      _locale = l;
      notifyListeners();
      _save();
    }
  }

  /// Restores the language chosen on this device, if any.
  Future<void> load() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final saved = prefs.getString(prefsKey);
      if (saved != null &&
          _supported.contains(saved) &&
          saved != _locale.languageCode) {
        _locale = Locale(saved);
        notifyListeners();
      }
    } catch (_) {
      // Keep the default.
    }
  }

  Future<void> _save() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(prefsKey, _locale.languageCode);
    } catch (_) {
      // Not saved; the choice still applies for this session.
    }
  }

  String t(String key) {
    final lang = _supported.contains(_locale.languageCode)
        ? _locale.languageCode
        : 'en';
    return (_messages[lang] ?? const {})[key] ?? _messages['en']![key] ?? key;
  }

  /// The line for [key] in [lang], whatever language is active. For
  /// screens that show both languages at once (the language picker).
  String tIn(String lang, String key) =>
      (_messages[lang] ?? const {})[key] ?? _messages['en']![key] ?? key;

  static const _supported = {'en', 'sw'};

  /// Every key defined for [lang], so tests can check both languages match.
  @visibleForTesting
  static Set<String> keysOf(String lang) =>
      (_messages[lang] ?? const {}).keys.toSet();

  /// The line for [key] in [lang] exactly as written, so tests can tell a
  /// translation from English left in place.
  @visibleForTesting
  static String? textOf(String lang, String key) => _messages[lang]?[key];

