      'auth.acceptAndClose': 'Kubali',
      'auth.termsContent':
          'Karibu FitFlex.\n\n1. MATUMIZI YA HUDUMA\nKwa kuunda akaunti unakubali kutumia FitFlex kwa mujibu wa sheria husika na Masharti haya.\n\n2. UANACHAMA\nPasi yako ya uanachama wa gym ni ya kibinafsi na haiwezi kuhamishiwa mtu mwingine. Kila kuingia kunathibitishwa kwa msimbo wa QR.\n\n3. MALIPO\nMalipo yanafanywa kulingana na mpango wa usajili uliochaguliwa. Marejesho yanategemea sera ya mmiliki wa gym.\n\n4. FARAGHA\nTunakusanya taarifa binafsi ili kutoa huduma za ufikiaji wa gym. Taarifa zako hazitauzwa kwa watu wengine. Angalia Sera yetu ya Faragha kwa maelezo kamili.\n\n5. KUSIMAMISHWA KWA AKAUNTI\nFitFlex ina haki ya kusimamisha akaunti zinazokiuka Masharti haya.\n\n6. MABADILIKO\nTunaweza kusasisha Masharti haya mara kwa mara. Kuendelea kutumia baada ya mabadiliko kunamaanisha umeyakubali.\n\nKwa maswali wasiliana: support@fitflexaf.co.tz',
